import{_ as t}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as l,d as a}from"./app-5d62b1ab.js";const s={},n=a(`<h1 id="ゲーム設定を編集する" tabindex="-1"><a class="header-anchor" href="#ゲーム設定を編集する" aria-hidden="true">#</a> ゲーム設定を編集する</h1><p><code>game</code> フォルダの下に <code>config.txt</code> というファイルがあり、このファイルにゲームの関連情報を記入することができます（グラフィカルなエディタを使って直接編集することもできます）。</p><table><thead><tr><th style="text-align:left;">パラメータ</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;">Game_name</td><td style="text-align:left;">ゲーム名</td></tr><tr><td style="text-align:left;">Game_key</td><td style="text-align:left;">ゲーム識別コード、長さ 6-10 文字、他のゲームと重複しないようにしてください</td></tr><tr><td style="text-align:left;">Title_img</td><td style="text-align:left;">タイトル画像、<code>background</code> フォルダに入れてください</td></tr><tr><td style="text-align:left;">Title_bgm</td><td style="text-align:left;">タイトルの BGM、<code>bgm</code> フォルダに入れてください</td></tr><tr><td style="text-align:left;">Game_Logo</td><td style="text-align:left;">ゲームのロゴ、複数表示することができ、| で区切ります</td></tr><tr><td style="text-align:left;">Enable_Appreciation</td><td style="text-align:left;">鑑賞機能（CGおよび背景音楽の鑑賞を含む）を有効にするかどうか。</td></tr><tr><td style="text-align:left;">Default_Language</td><td style="text-align:left;">デフォルト言語、「zh_CN」、「zh_TW」、「en」、「ja」、「fr」、「de」に設定可能。</td></tr><tr><td style="text-align:left;">Show_panic</td><td style="text-align:left;">パニックボタン機能を有効にするかどうか、true または false に設定</td></tr><tr><td style="text-align:left;">Legacy_Expression_Blend_Mode</td><td style="text-align:left;">Live2D の旧表情ブレンドモードを有効にするかどうか、true または false に設定</td></tr><tr><td style="text-align:left;">Max_line</td><td style="text-align:left;">テキスト表示フレームの最大行数</td></tr><tr><td style="text-align:left;">Line_height</td><td style="text-align:left;">テキストフレームの行高(単位:em)</td></tr></tbody></table><p>以下は設定ファイルの例です。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F8F8F2;">Game_name:WebGAL;</span></span>
<span class="line"><span style="color:#F8F8F2;">Game_key:0f33fdGr;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_img:Title.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Title_bgm:夏影.mp3;</span></span>
<span class="line"><span style="color:#F8F8F2;">Game_Logo:WebGalEnter.png|bg.png;</span></span>
<span class="line"><span style="color:#F8F8F2;">Enable_Appreciation:true;</span></span>
<span class="line"><span style="color:#F8F8F2;"></span></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="言語の切り替え" tabindex="-1"><a class="header-anchor" href="#言語の切り替え" aria-hidden="true">#</a> 言語の切り替え</h2><p><code>Default_Language</code> は、プレイヤーが初回起動したときのデフォルトの UI 言語を設定するための項目です。プレイヤーはその後もゲームメニューの <code>オプション -&gt; システム -&gt; Language</code> から言語を切り替えることができ、選択結果はローカルに保存され、次回起動時にも優先して使われます。</p><p>複数言語のスクリプトも用意している場合は、スクリプト内で現在の UI 言語を読み取り、対応するシーンファイルへ分岐してください。内部変数 <code>$userData.optionData.language</code> を利用できます。</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">setVar</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">lang=($userData.optionData.language)</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_zh.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==0</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_en.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==1</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeScene</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">start_ja.txt </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">when</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">lang==2</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>各数値と言語の対応は次のとおりです。</p><table><thead><tr><th style="text-align:left;">値</th><th style="text-align:left;">言語</th></tr></thead><tbody><tr><td style="text-align:left;">0</td><td style="text-align:left;">简体中文</td></tr><tr><td style="text-align:left;">1</td><td style="text-align:left;">English</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">日本語</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">Français</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">Deutsch</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">繁體中文</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">ヒント</p><p>メニューでの言語切り替えは、エンジン UI の言語を変更します。ゲーム本文も連動して切り替えたい場合は、上記のようにスクリプト側で言語ごとのシーンへ分岐してください。</p></div>`,12),d=[n];function i(r,o){return e(),l("div",null,d)}const g=t(s,[["render",i],["__file","config.html.vue"]]);export{g as default};
